              const qty = line.revisions ? line.revisions.quantity : line.quantity;
              revisedTotal += qty * line.rate;
              originalTotal += line.quantity * line.rate;
              if (line.revisions) hasRevision = true;
            });
          });
        });
        grandTotal += revisedTotal;
        grandOriginal += originalTotal;
        const totalCell = hasRevision
          ? `${revisedTotal.toLocaleString()}<br><span class="old-val">${originalTotal.toLocaleString()}</span>`
          : revisedTotal.toLocaleString();
        return `
          <tr class="summary-row">
            <th colspan="5" style="text-align:start;font-weight:bold">SERIES ${x + 1} - <span style="font-size:8px;">${serie.name}</span></th>
            <th colspan="1" style="text-align:end">${totalCell}</th>
          </tr>`;
      }).join("");
      const grandCell = grandTotal !== grandOriginal
        ? `${grandTotal.toLocaleString()}<br><span class="old-val">${grandOriginal.toLocaleString()}</span>`
        : grandTotal.toLocaleString();
      return rowsHtml + `
        <tr class="grand-total">
          <th colspan="5" style="text-align:start">A Total of Bills</th>
          <th colspan="1" style="text-align:end">${grandCell}</th>
        </tr>`;
    })()}
  </tbody>
</table>

</body>
</html>
`;

        const iframeDoc = iframe.contentWindow.document;
        iframeDoc.open();
        iframeDoc.write(printContent);
        iframeDoc.close();

        iframe.onload = () => {
            iframe.contentWindow.focus();
            iframe.contentWindow.print();
            setTimeout(() => {
                document.body.removeChild(iframe);
            }, 1000);
        };
    } catch (error) {
        console.error('Print error:', error);
        showError(`Failed to print boq ${error.message}`);
    }
};
